//! 🏠️ Bounded native slot and return-inbox storage carries data without minting a Source capability.
use std::{cell::UnsafeCell,sync::atomic::{AtomicU8,AtomicU64,Ordering}};
use semio_framework_value_retained_clone::retirement::controlled::RetainedOwnerGate;
pub struct NativeSlot<E:?Sized>{pub generation:u64,pub closed_generation:u64,pub loans:usize,pub bytes:usize,pub root:Option<Box<E>>}
pub struct NativeReturnCell<R>{pub state:AtomicU8,pub serial:AtomicU64,pub record:UnsafeCell<Option<R>>}
unsafe impl<R:Send> Send for NativeReturnCell<R>{}
unsafe impl<R:Send> Sync for NativeReturnCell<R>{}
impl<R> NativeReturnCell<R>{fn new()->Self{Self{state:AtomicU8::new(0),serial:AtomicU64::new(0),record:UnsafeCell::new(None)}}}
pub struct NativeSources<R,E:?Sized,const SLOTS:usize,const RETURNS:usize>{pub slots:RetainedOwnerGate<[NativeSlot<E>;SLOTS]>,pub returns:[NativeReturnCell<R>;RETURNS],reservation:RetainedOwnerGate<()>}
impl<R,E:?Sized,const SLOTS:usize,const RETURNS:usize> NativeSources<R,E,SLOTS,RETURNS>{pub fn new()->Self{Self{slots:RetainedOwnerGate::new(std::array::from_fn(|_|NativeSlot{generation:0,closed_generation:0,loans:0,bytes:0,root:None})),returns:std::array::from_fn(|_|NativeReturnCell::new()),reservation:RetainedOwnerGate::new(())}}pub fn pending(&self)->bool{self.returns.iter().any(|cell|cell.state.load(Ordering::Acquire)!=0)||self.slots.try_lock().map_or(true,|slots|slots.iter().any(|slot|slot.root.is_some()||slot.loans!=0))}pub fn reserve<F>(&self,record:impl FnOnce()->Result<Option<R>,F>)->Result<Option<usize>,F>{let Ok(_reservation)=self.reservation.try_lock()else{return Ok(None)};let Some(index)=self.returns.iter().position(|cell|cell.serial.load(Ordering::Acquire)<u64::MAX&&cell.state.load(Ordering::Acquire)==0)else{return Ok(None)};let Some(record)=record()?else{return Ok(None)};self.returns[index].serial.fetch_add(1,Ordering::Relaxed);unsafe{*self.returns[index].record.get()=Some(record)};self.returns[index].state.store(1,Ordering::Release);Ok(Some(index))}}

#[cfg(test)]mod tests{use super::*;#[test]fn funded_native_reservation_never_mutates_an_unfunded_or_failed_row(){let law:serde_json::Value=serde_json::from_str(include_str!("🧪️tests/🧫️fixtures/reservation.json")).unwrap();for row in law["cases"].as_array().unwrap(){let bank=NativeSources::<u64,(),1,1>::new();let result=bank.reserve(||match row["producer"].as_str().unwrap(){"blocked"=>Ok(None),"failure"=>Err("actual funding refusal"),"ready"=>Ok(Some(41)),_=>unreachable!()});assert_eq!(result.is_err(),row["producer"]=="failure");assert_eq!(bank.returns[0].state.load(Ordering::Acquire),row["state"].as_u64().unwrap()as u8);assert_eq!(bank.returns[0].serial.load(Ordering::Acquire),row["serial"].as_u64().unwrap());assert_eq!(unsafe{(&*bank.returns[0].record.get()).is_some()},row["record"].as_bool().unwrap());}let bank=NativeSources::<u64,(),1,1>::new();let hold=bank.reservation.try_lock().unwrap();let mut called=false;assert_eq!(bank.reserve(||{called=true;Ok::<_,()>(Some(1))}).unwrap(),None);assert!(!called);assert_eq!(bank.returns[0].state.load(Ordering::Acquire),0);drop(hold);}}
